package got;
import net.minecraft.core.RegistryAccess;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.SimpleContainer;import net.minecraft.world.inventory.CraftingContainer;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.CraftingBookCategory;import net.minecraft.world.item.crafting.CustomRecipe;import net.minecraft.world.item.crafting.RecipeSerializer;import net.minecraft.world.level.Level;import javax.annotation.Nullable;import java.util.ArrayList;import java.util.List;
/** Legacy pouch-upgrade recipe: combines smaller pouch capacities while preserving contents. */
public final class GOTPouchCombineRecipe extends CustomRecipe{
 public GOTPouchCombineRecipe(ResourceLocation id,CraftingBookCategory cat){super(id,cat);}public boolean matches(CraftingContainer c,Level l){return build(c)!=null;}public ItemStack assemble(CraftingContainer c,RegistryAccess a){ItemStack s=build(c);return s==null?ItemStack.EMPTY:s;}@Nullable private static ItemStack build(CraftingContainer c){List<ItemStack> pouches=new ArrayList<>();int capacity=0;for(int i=0;i<c.getContainerSize();i++){ItemStack s=c.getItem(i);if(s.isEmpty())continue;if(!(s.getItem() instanceof GOTPouchItem p))return null;pouches.add(s);capacity+=p.capacity();}if(pouches.size()<2||capacity>27)return null;ItemStack out=new ItemStack(capacity<=9?GOTItems.POUCH_SMALL.get():capacity<=18?GOTItems.POUCH_MEDIUM.get():GOTItems.POUCH_LARGE.get());int outCap=((GOTPouchItem)out.getItem()).capacity();SimpleContainer dst=new SimpleContainer(outCap);int at=0;for(ItemStack pouch:pouches){GOTPouchItem pi=(GOTPouchItem)pouch.getItem();SimpleContainer src=GOTPouchItem.load(pouch,pi.capacity());for(int j=0;j<src.getContainerSize();j++)if(!src.getItem(j).isEmpty()){while(at<outCap&&!dst.getItem(at).isEmpty())at++;if(at>=outCap)return null;dst.setItem(at++,src.getItem(j).copy());}}GOTPouchItem.save(out,dst);if(pouches.get(0).getItem() instanceof net.minecraft.world.item.DyeableLeatherItem d && d.hasCustomColor(pouches.get(0)))((net.minecraft.world.item.DyeableLeatherItem)out.getItem()).setColor(out,d.getColor(pouches.get(0)));return out;}public boolean canCraftInDimensions(int w,int h){return w*h>=2;}public RecipeSerializer<?> getSerializer(){return GOTRecipes.POUCH_COMBINE.get();}}
